sys_script_include.script:
var EventUtils2 = Class.create();
EventUtils2.prototype = {
    initialize: function() {
    },

    getEventDetails: function(eventId) {
        var result = {};
        var gr = new GlideRecord('Event_Record'); 
        if (gr.get(eventId)) {
            result.name = gr.getValue('u_event_name');
            result.date = gr.getValue('u_event_date');
            result.location = gr.getValue('u_location');
        }
        return result;
    },



    type: 'EventUtils2'
};
